sp_widget.client_script:
api.controller = function($scope, spUtil) {
    var c = this;

    c.buy = function(subscriptionType) {
			//spUtil.addInfoMessage("SubUpdated");
		c.server.get({ subscription: subscriptionType }).then(function(res) {
            var name = res.data.sub;
			if(name=="Advance")
				{
					spUtil.addInfoMessage("Already you have this plan");
				}
			else
				{
					spUtil.addInfoMessage("substripbed");

				}

        });
    };
};

sp_widget.script:
(function() {
    var subscription = input && input.subscription ? input.subscription : null;

    if (subscription) {

        var user = new GlideRecord("sys_user");
        user.addQuery('sys_id', gs.getUserID());
        user.query();

        if (user.next()) {
            var username = user.user_name.toString();  // Get the username as string


            var gr = new GlideRecord("x_1811084_diya_c_0_customer_profile");
            gr.addQuery("user_id", username); 
            gr.query();

            if (gr.next()) {
							var  sub=gr.getValue("subscription");
							data.sub=sub;
                gr.setValue("subscription", subscription);
                gr.update();
						}
				}
		}
})();
